let readyPromise;
function ready(){return readyPromise??=new Promise((resolve,reject)=>{if(!window.meSpeak){reject(new Error('Speech pack unavailable'));return;}window.meSpeak.loadVoice('de',(ok)=>ok?resolve():reject(new Error('German voice unavailable')));});}
const streams=new Map();
function synthesize(text,mode){const key=mode+':'+text;if(streams.has(key))return streams.get(key);const task=ready().then(()=>new Promise((resolve,reject)=>window.meSpeak.speak(text,{voice:'de',variant:mode==='screech'?'f5':mode==='passenger'?'f3':'croak',pitch:mode==='passenger'?60:90,speed:mode==='passenger'?175:165,amplitude:110,rawdata:true,ssml:false},(ok,id,data)=>ok?resolve(data):reject(new Error('Speech synthesis failed')))));streams.set(key,task);task.catch(()=>streams.delete(key));if(streams.size>40)streams.delete(streams.keys().next().value);return task;}
export function createParrotVoice(getAudio,isSoundOn){let token=0,source=null,tremolo=null;function stop(){token++;try{source?.stop();tremolo?.stop();}catch{}source=tremolo=null;window.speechSynthesis?.cancel();}
  async function say(text,mode='croak'){stop();if(!isSoundOn())return;const request=token,audio=getAudio();if(!audio)return;
    if(mode==='passenger'&&'speechSynthesis'in window){const voices=window.speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.startsWith('de')&&/Katja|Hedda|Anna|Petra|Marlene|Helena/i.test(v.name));if(voice){const line=new SpeechSynthesisUtterance(text);line.voice=voice;line.lang='de-DE';line.pitch=1.15;line.rate=1.1;line.volume=.9;audio.voiceUntil=audio.ctx.currentTime+3;line.onend=()=>audio.voiceUntil=0;window.speechSynthesis.speak(line);return {engine:'system'};}}
    try{const bytes=await synthesize(text,mode);if(request!==token||!isSoundOn())return;const buffer=await audio.ctx.decodeAudioData(bytes.slice(0));if(request!==token||!isSoundOn())return;
      source=audio.ctx.createBufferSource();source.buffer=buffer;source.playbackRate.value=mode==='screech'?1.28:mode==='passenger'?1:1.15;const gain=audio.ctx.createGain();gain.gain.value=mode==='passenger'?.62:.48;
      if(mode==='passenger')source.connect(gain);else{const filter=audio.ctx.createBiquadFilter();filter.type='bandpass';filter.frequency.value=mode==='screech'?1850:1350;filter.Q.value=.55;const rasp=audio.ctx.createWaveShaper(),curve=new Float32Array(2048);for(let i=0;i<curve.length;i++)curve[i]=Math.tanh((i/(curve.length-1)*2-1)*3.2);rasp.curve=curve;rasp.oversample='2x';source.connect(filter);filter.connect(rasp);rasp.connect(gain);tremolo=audio.ctx.createOscillator();const depth=audio.ctx.createGain();tremolo.frequency.value=mode==='screech'?49:33;depth.gain.value=.13;tremolo.connect(depth);depth.connect(gain.gain);tremolo.start();tremolo.stop(audio.ctx.currentTime+buffer.duration/source.playbackRate.value+.05);}
      gain.connect(audio.master);audio.voiceUntil=audio.ctx.currentTime+buffer.duration/source.playbackRate.value;source.start();source.onended=()=>{if(request===token)audio.voiceUntil=0;};return {engine:'meSpeak',duration:buffer.duration/source.playbackRate.value};
    }catch{if(request!==token||!isSoundOn()||!('speechSynthesis'in window))return;const line=new SpeechSynthesisUtterance(text);line.lang='de-DE';line.pitch=mode==='passenger'?1.2:2;line.rate=1.16;window.speechSynthesis.speak(line);return {engine:'browser'};}
  }
  return {say,stop,prepare:()=>ready().catch(()=>{})};
}
